func testPlanoContasFinanceiroToOneContaBancariumUsingCTB(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local PlanoContasFinanceiro
	var foreign ContaBancarium

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, planoContasFinanceiroDBTypes, true, planoContasFinanceiroColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize PlanoContasFinanceiro struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, contaBancariumDBTypes, false, contaBancariumColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize ContaBancarium struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.CTBID, foreign.CTBID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.CTB().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.CTBID, foreign.CTBID) {
		t.Errorf("want: %v, got %v", foreign.CTBID, check.CTBID)
	}

	ranAfterSelectHook := false
	AddContaBancariumHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *ContaBancarium) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := PlanoContasFinanceiroSlice{&local}
	if err = local.L.LoadCTB(ctx, tx, false, (*[]*PlanoContasFinanceiro)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.CTB == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.CTB = nil
	if err = local.L.LoadCTB(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.CTB == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

